import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, MAX_ATTEMPTS, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;

const db = openDatabase();
let stopping = false;
let currentJobId: string | null = null;

const now = () => new Date().toISOString();

function heartbeat(): void {
  try {
    db.prepare('INSERT INTO heartbeat (name, beat_at) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET beat_at = excluded.beat_at')
      .run('worker', Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}

/**
 * Puts interrupted (running) jobs back in the queue. The interrupted attempt is redone; if it was
 * already the last allowed attempt it is redone under the same attempt number so the total never
 * exceeds MAX_ATTEMPTS.
 */
function requeue(where: string, ...params: string[]): void {
  db.prepare(`
    UPDATE jobs SET status = 'queued', progress = 0, next_run_at = 0, updated_at = ?,
      attempts = CASE WHEN attempts >= ${MAX_ATTEMPTS} THEN ${MAX_ATTEMPTS - 1} ELSE attempts END
    WHERE status = 'running' ${where}
  `).run(now(), ...params);
}

function claim(): JobRow | undefined {
  return db.prepare(`
    UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ?
    WHERE id = (
      SELECT id FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1
    ) AND status = 'queued'
    RETURNING *
  `).get(now(), Date.now()) as JobRow | undefined;
}

async function process(job: JobRow): Promise<void> {
  currentJobId = job.id;
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // left running; requeued on shutdown
    if (step === 1 && attempt <= job.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) {
        db.prepare(`UPDATE jobs SET status = 'failed', error = 'transient failure', output = NULL, progress = 0, updated_at = ? WHERE id = ? AND status = 'running'`)
          .run(now(), job.id);
      } else {
        db.prepare(`UPDATE jobs SET status = 'queued', progress = 0, next_run_at = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
          .run(Date.now() + RETRY_DELAY_MS, now(), job.id);
      }
      currentJobId = null;
      return;
    }
    if (step < job.steps) {
      db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(step, now(), job.id);
    } else {
      db.prepare(`UPDATE jobs SET status = 'completed', progress = ?, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'`)
        .run(step, job.input.toUpperCase(), now(), job.id);
    }
  }
  currentJobId = null;
}

// Only one worker is expected; anything still running belongs to a dead worker.
requeue('');
