let stopping = false;
let currentJobId: string | null = null;

const now = () => new Date().toISOString();

function heartbeat(): void {
  try {
    db.prepare('INSERT INTO heartbeat (name, beat_at) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET beat_at = excluded.beat_at')
      .run('worker', Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}

/**
 * Puts interrupted (running) jobs back in the queue. The interrupted attempt is redone; if it was
 * already the last allowed attempt it is redone under the same attempt number so the total never
 * exceeds MAX_ATTEMPTS.
 */
function requeue(where: string, ...params: string[]): void {
  db.prepare(`
    UPDATE jobs SET status = 'queued', progress = 0, next_run_at = 0, updated_at = ?,
      attempts = CASE WHEN attempts >= ${MAX_ATTEMPTS} THEN ${MAX_ATTEMPTS - 1} ELSE attempts END
    WHERE status = 'running' ${where}
  `).run(now(), ...params);
}

function claim(): JobRow | undefined {
  return db.prepare(`
    UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ?
    WHERE id = (
      SELECT id FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1
    ) AND status = 'queued'
    RETURNING *
  `).get(now(), Date.now()) as JobRow | undefined;
}

async function process(job: JobRow): Promise<void> {
  currentJobId = job.id;
  const attempt = job.attempts;
